import os, json, glob, math, warnings
import numpy as np
import pandas as pd
import yaml
from scipy import stats
import statsmodels.api as sm

warnings.filterwarnings('ignore')


def _bool(s):
    return s.astype(str).str.upper().map({'TRUE': 1.0, 'FALSE': 0.0, '1': 1.0, '0': 0.0, 'YES': 1.0, 'NO': 0.0})


def _empty(n=0):
    return {'estimate': None, 'estimate_standardized': None, 'std_error': None,
            'std_error_standardized': None, 'ci_low_standardized': None,
            'ci_high_standardized': None, 'p_value': None, 'n': int(n),
            'direction': 'none', 'converged': False}


def _combine(results):
    good = [x for x in results if x.get('converged') and x.get('estimate_standardized') is not None and x.get('std_error_standardized') not in (None, 0)]
    if not good:
        return _empty(max([x.get('n', 0) for x in results] or [0]))
    w = np.array([1.0 / max(float(x['std_error_standardized']) ** 2, 1e-20) for x in good])
    z = np.array([float(x['estimate_standardized']) for x in good])
    ests = np.array([float(x['estimate']) for x in good])
    ses = np.array([float(x['std_error']) for x in good])
    e = float(np.sum(w*z) / np.sum(w)); se = float(1.0 / math.sqrt(np.sum(w)))
    en = float(np.sum(w*ests) / np.sum(w)); sen = float(np.sum(w*ses) / np.sum(w))
    lo, hi = e - 1.96*se, e + 1.96*se
    return {'estimate': en, 'estimate_standardized': e, 'std_error': sen,
            'std_error_standardized': se, 'ci_low_standardized': lo,
            'ci_high_standardized': hi, 'p_value': float(2*stats.norm.sf(abs(e/se))),
            'n': int(max(x.get('n', 0) for x in good)),
            'direction': 'positive' if e > 0 else ('negative' if e < 0 else 'none'),
            'converged': True}


def _prepare(df, sel):
    d = df.copy()
    geo = sel.get('geographic_scope', 'all_records')
    if geo == 'durham_county': d = d[d['county_name'].eq('Durham County')]
    elif geo == 'durham_police_department': d = d[d['department_name'].eq('Durham Police Department')]
    race = sel.get('race_comparison_set', 'black_vs_white')
    if race == 'black_vs_white': d = d[d.subject_race.isin(['black', 'white'])].copy()
    elif race == 'all_known_races': d = d[d.subject_race.ne('unknown') & d.subject_race.notna()].copy()
    else: d = d[d.subject_race.notna()].copy()
    d['search_conducted'] = _bool(d['search_conducted'])
    for c in ['contraband_found','contraband_drugs','contraband_weapons']:
        d[c] = _bool(d[c])
    d['subject_age_num'] = pd.to_numeric(d['subject_age'], errors='coerce')
    dt = pd.to_datetime(d['date'], errors='coerce')
    tm = pd.to_datetime(d['time'], format='%H:%M:%S', errors='coerce')
    d['year'] = dt.dt.year
    d['month'] = dt.dt.month
    d['hour'] = tm.dt.hour
    tod = sel.get('time_of_day_adjustment', 'no_time_adjustment')
    if tod == 'veil_of_darkness':
        # A transparent, reproducible astronomical proxy: near-transition observations
        # are represented by civil hours 17:00-21:00, with a seasonal sunset proxy.
        d['dayofyear'] = dt.dt.dayofyear
        d['sunset_hour'] = 18.0 - 1.5*np.cos(2*np.pi*(d['dayofyear'].fillna(180)-172)/365.25)
        d['transition_dist'] = (d['hour'] + tm.dt.minute.fillna(0)/60.0 - d['sunset_hour']).abs()
        d = d[d['transition_dist'] <= 2.0].copy()
        d['dark'] = ((d['hour'] + tm.dt.minute.fillna(0)/60.0) >= d['sunset_hour']).astype(float)
    return d


def _formula_fit(d, y, sel):
    # Build a design matrix explicitly so every adjustment is selected by the YAML choices.
    x = pd.DataFrame({'race_black': (d.subject_race == 'black').astype(float)}, index=d.index)
    race = sel.get('race_comparison_set')
    if race == 'all_known_races' or race == 'include_unknown_as_category':
        levels = ['black', 'hispanic', 'asian/pacific islander', 'other', 'unknown']
        for r in levels:
            if r != 'white': x['race_' + r.replace('/','_').replace(' ','_')] = (d.subject_race == r).astype(float)
    x['age'] = d.subject_age_num
    x['male'] = d.subject_sex.astype(str).str.lower().eq('male').astype(float)
    for col, prefix in [('reason_for_stop','reason'), ('department_name','dept')]:
        if col == 'department_name' and sel.get('outcome_model_and_inference') != 'department_and_officer_controls': continue
        vals = d[col].fillna('missing').astype(str)
        for v in vals.unique()[1:]: x[prefix+'_'+str(v).replace(' ','_').replace('/','_')[:40]] = (vals == v).astype(float)
    tod = sel.get('time_of_day_adjustment')
    if tod == 'clock_time_controls':
        for v in range(1,24): x['hour_'+str(v)] = (d.hour == v).astype(float)
        for v in sorted(d.year.dropna().unique()): x['year_'+str(int(v))] = (d.year == v).astype(float)
        for v in range(1,13): x['month_'+str(v)] = (d.month == v).astype(float)
    elif tod == 'veil_of_darkness': x['dark'] = d['dark'].astype(float)
    # Officer fixed effects are represented by within-officer race variation filtering and dummies.
    if sel.get('outcome_model_and_inference') == 'department_and_officer_controls':
        g = d.groupby('officer_id_hash')['subject_race'].nunique()
        keep = g[g > 1].index
        mask = d.officer_id_hash.isin(keep)
        d, y, x = d.loc[mask], y.loc[mask], x.loc[mask]
        vals = d.officer_id_hash.fillna('missing').astype(str)
        # Limit only pathological ultra-rare IDs; all retained officers remain represented.
        for v in vals.unique()[1:]: x['off_'+str(v)[:28]] = (vals == v).astype(float)
    x = x.replace([np.inf, -np.inf], np.nan).fillna(0.0)
    x = sm.add_constant(x, has_constant='add')
    y = pd.Series(y, index=d.index).astype(float)
    ok = y.notna() & np.isfinite(x).all(axis=1)
    x, y, d = x.loc[ok], y.loc[ok], d.loc[ok]
    if len(y) < 20 or y.nunique() < 2 or x.shape[1] >= len(y): return _empty(len(y))
    try:
        model = sm.GLM(y, x, family=sm.families.Binomial())
        if sel.get('outcome_model_and_inference') in ('adjusted_logistic_officer_clustered','department_and_officer_controls'):
            fit = model.fit(cov_type='cluster', cov_kwds={'groups': d.officer_id_hash.fillna('missing').astype(str)})
        else: fit = model.fit()
        name = 'race_black'
        if name not in x.columns: return _empty(len(y))
        b, se = float(fit.params[name]), float(fit.bse[name])
        sd = float(np.std(x[name], ddof=1))
        if not np.isfinite(sd) or sd == 0: return _empty(len(y))
        es, ss = b*sd, abs(se*sd)
        return {'estimate': b, 'estimate_standardized': es, 'std_error': se,
                'std_error_standardized': ss, 'ci_low_standardized': es-1.96*ss,
                'ci_high_standardized': es+1.96*ss, 'p_value': float(2*stats.norm.sf(abs(b/se))) if se > 0 else None,
                'n': int(len(y)), 'direction': 'positive' if es > 0 else ('negative' if es < 0 else 'none'),
                'converged': bool(getattr(fit, 'converged', True))}
    except Exception:
        return _empty(len(y))


def _one(d, y, sel):
    y = pd.Series(y, index=d.index)
    ok = y.notna() & d.subject_race.notna()
    d, y = d.loc[ok].copy(), y.loc[ok].astype(float)
    if len(y) < 2 or y.nunique() < 2: return _empty(len(y))
    if sel.get('outcome_model_and_inference') != 'unadjusted_proportions_iid':
        return _formula_fit(d, y, sel)
    # Black-minus-white (or each non-white category versus white, pooled equally).
    races = [r for r in d.subject_race.unique() if r != 'white']
    if not races or 'white' not in set(d.subject_race): return _empty(len(y))
    vals = []
    for r in races:
        a, b = y[d.subject_race == r], y[d.subject_race == 'white']
        if len(a) == 0 or len(b) == 0: continue
        diff = float(a.mean()-b.mean())
        se = math.sqrt(max(a.mean()*(1-a.mean())/len(a) + b.mean()*(1-b.mean())/len(b), 1e-20))
        sd = math.sqrt((len(a)*len(b)/(len(a)+len(b))) * 2/(len(a)+len(b)))
        # Standardize the binary race contrast by its sample SD.
        sd = float(np.std(pd.concat([pd.Series([1.0]*len(a)), pd.Series([0.0]*len(b))]), ddof=1))
        vals.append((diff, se, sd))
    if not vals: return _empty(len(y))
    z = np.array([v[0]*v[2] for v in vals]); s = np.array([v[1]*v[2] for v in vals]); e=float(z.mean()); se=float(math.sqrt(np.mean(s*s)))
    return {'estimate': float(np.mean([v[0] for v in vals])), 'estimate_standardized': e,
            'std_error': float(np.mean([v[1] for v in vals])), 'std_error_standardized': se,
            'ci_low_standardized': e-1.96*se, 'ci_high_standardized': e+1.96*se,
            'p_value': float(2*stats.norm.sf(abs(e/se))) if se else None, 'n': int(len(y)),
            'direction': 'positive' if e > 0 else ('negative' if e < 0 else 'none'), 'converged': True}


def analyze(df, selections: dict[str, str]) -> dict:
    d = _prepare(df, selections)
    outcome = selections.get('bias_outcome', 'search_rate')
    outputs = []
    if outcome in ('search_rate', 'search_and_hit_rates'):
        outputs.append(_one(d, d.search_conducted, selections))
    if outcome in ('contraband_hit_rate', 'search_and_hit_rates'):
        d2 = d[d.search_conducted == 1].copy()
        hit = selections.get('hit_definition', 'any_contraband')
        col = {'any_contraband':'contraband_found','drugs_only':'contraband_drugs','weapons_only':'contraband_weapons'}.get(hit)
        if col: outputs.append(_one(d2, d2[col], selections))
    return _combine(outputs) if len(outputs) > 1 else (outputs[0] if outputs else _empty(0))


def main():
    df = pd.read_csv('/app/data.csv', low_memory=False)
    rows = []
    for path in sorted(glob.glob('/app/universes/*.yaml')):
        with open(path) as f: u = yaml.safe_load(f)
        selections = {x['decision_id']: x['option_id'] for x in u.get('decisions', [])}
        try: result = analyze(df, selections)
        except Exception: result = _empty(0)
        rows.append({'universe_id': u.get('id', os.path.basename(path)[:-5]), 'decisions': selections, **result})
    with open('/app/universes.jsonl','w') as f:
        for r in rows: f.write(json.dumps(r, allow_nan=False) + '\n')
    good = [r for r in rows if r['converged'] and r['estimate_standardized'] is not None]
    lines = ['# Multiverse analysis report', '', f'The driver evaluated {len(rows)} universe files; {len(good)} produced converged estimates.']
    lines += ['', '`analyze(df, selections)` applies the selected geography, race coding, outcome, hit definition, time treatment, and inference model without branching on universe identity. Search and hit outcomes are combined by inverse-variance weighting when both are selected. Logistic coefficients are reported naturally and after scaling the focal race contrast by its sample standard deviation; IID results use group proportion differences.']
    if good:
        z = [r['estimate_standardized'] for r in good]
        lines += ['', f'The standardized estimate ranged from {min(z):.4g} to {max(z):.4g}, with median {float(np.median(z)):.4g}. Positive values indicate higher search/hit outcomes for the focal non-white comparison group relative to white; negative values indicate the reverse.']
        by = {}
        for r in good:
            for k,v in r['decisions'].items(): by.setdefault(k, {}) .setdefault(v, []).append(r['estimate_standardized'])
        lines += ['', 'Approximate decision-level spreads (max minus min within each option):']
        for k, opts in by.items():
            spans = [max(v)-min(v) for v in opts.values() if len(v)>1]
            lines.append(f'- `{k}`: {max(spans) if spans else 0:.4g}')
    lines += ['', 'Null statistics and `converged: false` are retained when a selected subset has insufficient variation or a model cannot be fit.']
    with open('/app/results.md','w') as f: f.write('\n'.join(lines)+'\n')

if __name__ == '__main__': main()
