        clock=d['hour'].fillna(12)+tm.dt.minute.fillna(0)/60
        d['sunset']=sunset; d['dist']=(clock-sunset).abs()
        d=d[d.dist<=2].copy(); d['dark']=(clock>=sunset).astype(float)
    return d


def binary_result(d,y,s):
    y=pd.Series(y,index=d.index)
    ok=y.notna() & d.subject_race.notna()
    d=d.loc[ok].copy(); y=y.loc[ok].astype(float)
    if len(y)<20 or y.nunique()<2 or 'white' not in set(d.subject_race): return empty(len(y))
    model=s.get('outcome_model_and_inference','unadjusted_proportions_iid')
    races=['black'] if s.get('race_comparison_set')=='black_vs_white' else [r for r in d.subject_race.unique() if r!='white']
    races=[r for r in races if r in set(d.subject_race)]
    if not races: return empty(len(y))
    if model=='unadjusted_proportions_iid':
        vals=[]
        for r in races:
            a=y[d.subject_race.eq(r)]; b=y[d.subject_race.eq('white')]
            if len(a)<2 or len(b)<2: continue
            diff=float(a.mean()-b.mean())
            se=math.sqrt(max(a.mean()*(1-a.mean())/len(a)+b.mean()*(1-b.mean())/len(b),1e-20))
            race_sd=float(np.std(np.r_[np.ones(len(a)),np.zeros(len(b))],ddof=1))
            vals.append((diff,se,race_sd))
        if not vals: return empty(len(y))
        est=float(np.mean([v[0] for v in vals])); sd=float(np.mean([v[2] for v in vals])); se=float(math.sqrt(np.mean([(v[1]*v[2])**2 for v in vals])))
        es=est*sd
        return {'estimate':est,'estimate_standardized':es,'std_error':float(np.mean([v[1] for v in vals])),'std_error_standardized':se,
