                'p_value':float(2*stats.norm.sf(abs(es/se))) if se else None,'n':len(y),
                'direction':'positive' if es>0 else ('negative' if es<0 else 'none'),'converged':True}
    x=pd.DataFrame(index=d.index)
    raceopt=s.get('race_comparison_set')
    if raceopt=='black_vs_white': x['race']=(d.subject_race=='black').astype(float)
    else:
        # The black indicator is the focal contrast; other race indicators are controls.
        x['race']=(d.subject_race=='black').astype(float)
        for r in ['hispanic','asian/pacific islander','other','unknown']:
            if r in set(d.subject_race): x['race_'+r.replace('/','_').replace(' ','_')]=(d.subject_race==r).astype(float)
    x['age']=d.age_num.fillna(d.age_num.median()); x['male']=d.subject_sex.astype('string').str.lower().eq('male').astype(float)
    for col,prefix in [('reason_for_stop','reason')]:
        vals=d[col].fillna('missing').astype(str)
        for v in vals.value_counts().head(20).index[1:]: x[prefix+'_'+v.replace(' ','_')[:30]]=(vals==v).astype(float)
    if model=='department_and_officer_controls':
        vals=d.department_name.fillna('missing').astype(str)
        for v in vals.value_counts().index[1:]: x['dept_'+v.replace(' ','_')[:30]]=(vals==v).astype(float)
        # Retain only officers with race variation, avoiding a prohibitively large dense FE matrix.
        varying=d.groupby('officer_id_hash').subject_race.nunique()
        d=d[d.officer_id_hash.isin(varying[varying>1].index)]; y=y.loc[d.index]; x=x.loc[d.index]
    tod=s.get('time_of_day_adjustment')
    if tod=='clock_time_controls':
        for h in range(1,24): x['h'+str(h)]=(d.hour==h).astype(float)
        for m in range(1,12): x['m'+str(m)]=(d.month==m).astype(float)
        for yr in sorted(d.year.dropna().unique()): x['y'+str(int(yr))]=(d.year==yr).astype(float)
    elif tod=='veil_of_darkness': x['dark']=d.dark.astype(float)
    x=sm.add_constant(x.replace([np.inf,-np.inf],np.nan).fillna(0),has_constant='add')
    if len(y)<20 or y.nunique()<2: return empty(len(y))
    try:
        fit=sm.GLM(y,x,family=sm.families.Binomial())
        if model in ('adjusted_logistic_officer_clustered','department_and_officer_controls'):
            res=fit.fit(cov_type='cluster',cov_kwds={'groups':d.officer_id_hash.fillna('missing').astype(str)})
        else: res=fit.fit()
        b=float(res.params['race']); se=float(res.bse['race']); rsd=float(np.std(x['race'],ddof=1))
        if not np.isfinite(b+se+rsd) or rsd<=0 or se<=0: return empty(len(y))
