                'p_value':float(2*stats.norm.sf(abs(b/se))),'n':len(y),
                'direction':'positive' if es>0 else ('negative' if es<0 else 'none'),
                'converged':bool(getattr(res,'converged',True))}
    except Exception: return empty(len(y))


def combine(rs):
    good=[r for r in rs if r.get('converged') and r.get('estimate_standardized') is not None and r.get('std_error_standardized',0)>0]
    if not good: return empty(max([r.get('n',0) for r in rs] or [0]))
    w=np.array([1/r['std_error_standardized']**2 for r in good]); z=np.array([r['estimate_standardized'] for r in good]); e=float(np.sum(w*z)/sum(w)); se=float(1/math.sqrt(sum(w)))
    return {'estimate':float(np.average([r['estimate'] for r in good],weights=w)),'estimate_standardized':e,
            'std_error':float(np.average([r['std_error'] for r in good],weights=w)),'std_error_standardized':se,
            'ci_low_standardized':e-1.96*se,'ci_high_standardized':e+1.96*se,
            'p_value':float(2*stats.norm.sf(abs(e/se))),'n':int(max(r['n'] for r in good)),
            'direction':'positive' if e>0 else ('negative' if e<0 else 'none'),'converged':True}


