        d2=d[d.search_conducted.eq(1)].copy(); col={'any_contraband':'contraband_found','drugs_only':'contraband_drugs','weapons_only':'contraband_weapons'}.get(selections.get('hit_definition'))
        if col: rs.append(binary_result(d2,d2[col],selections))
    return combine(rs) if len(rs)>1 else (rs[0] if rs else empty(0))


def main():
    df=pd.read_csv('/app/data.csv',low_memory=False)
    rows=[]
    for path in sorted(glob.glob('/app/universes/*.yaml')):
        with open(path) as f: u=yaml.safe_load(f)
        sel={x['decision_id']:x['option_id'] for x in u['decisions']}
        try: r=analyze(df,sel)
        except Exception: r=empty(0)
        rows.append({'universe_id':u['id'],'decisions':sel,**r})
    with open('/app/universes.jsonl','w') as f:
        for r in rows: f.write(json.dumps(r,allow_nan=False)+'\n')
    good=[r for r in rows if r['converged'] and r['estimate_standardized'] is not None]
    vals=[r['estimate_standardized'] for r in good]
    lines=['# Multiverse analysis report','',f'Evaluated {len(rows)} universe files; {len(good)} produced converged estimates.','',
    'The parameterized `analyze` function applies geography, race coding, outcome and hit definitions, time adjustments, and inference choices from `selections`. Unadjusted universes use race-group proportion differences. Adjusted universes use logistic regression with age, sex, stop-reason, and selected time controls; officer-clustered covariance is used for clustered specifications. Estimates are standardized by the sample SD of the focal race indicator. Search-and-hit universes combine the two outcome estimates by inverse-variance weighting.']
    if vals:
        lines += ['',f'Standardized estimates range from {min(vals):.5g} to {max(vals):.5g}; median {np.median(vals):.5g}. Positive values indicate a higher outcome for the focal black/non-white comparison relative to white.']
        for k in ['geographic_scope','race_comparison_set','bias_outcome','hit_definition','time_of_day_adjustment','outcome_model_and_inference']:
            groups={}
            for r in good: groups.setdefault(r['decisions'].get(k),[]).append(r['estimate_standardized'])
            spans=[max(v)-min(v) for v in groups.values() if len(v)>1]
            lines.append(f'- {k}: maximum within-option spread {max(spans) if spans else 0:.5g}')
    lines += ['', 'Failed or unidentified fits retain null statistics and `converged: false`; no verdict field is emitted.']
    with open('/app/results.md','w') as f: f.write('\n'.join(lines)+'\n')

